import React from 'react';
import { Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';

// Pages
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import IssueReport from './pages/IssueReport';
import IssueTracking from './pages/IssueTracking';
import Notifications from './pages/Notifications';
import AdminPanel from './pages/AdminPanel';
import IssueDetails from './pages/IssueDetails';
import Profile from './pages/Profile';
import Settings from './pages/Settings';
import Reports from './pages/Reports';
import StaffManagement from './pages/StaffManagement';
import SchoolInfo from './pages/SchoolInfo';
import About from './pages/About';
import Contact from './pages/Contact';
import PrivacyPolicy from './pages/PrivacyPolicy';
import TermsOfService from './pages/TermsOfService';
import HelpCenter from './pages/HelpCenter';
import FAQ from './pages/FAQ';

// More pages for 50+ (continuing in next file for brevity)
import FacilityList from './pages/FacilityList';
import FacilityDetails from './pages/FacilityDetails';
import RepairSchedule from './pages/RepairSchedule';
import VendorList from './pages/VendorList';
import BudgetManagement from './pages/BudgetManagement';
import Inventory from './pages/Inventory';
import SafetyInspection from './pages/SafetyInspection';
import ComplaintList from './pages/ComplaintList';
import Analytics from './pages/Analytics';
import UserManagement from './pages/UserManagement';

function App() {
  return (
    <div>
      <Navbar />
      <main className="min-vh-100">
        <Routes>
          {/* Public Pages */}
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/privacy" element={<PrivacyPolicy />} />
          <Route path="/terms" element={<TermsOfService />} />
          <Route path="/help" element={<HelpCenter />} />
          <Route path="/faq" element={<FAQ />} />

          {/* User Pages */}
          <Route path="/dashboard" element={<Dashboard />} />
          <Route path="/report-issue" element={<IssueReport />} />
          <Route path="/track-issues" element={<IssueTracking />} />
          <Route path="/notifications" element={<Notifications />} />
          <Route path="/profile" element={<Profile />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="/issue/:id" element={<IssueDetails />} />

          {/* Admin Pages */}
          <Route path="/admin" element={<AdminPanel />} />
          <Route path="/admin/reports" element={<Reports />} />
          <Route path="/admin/staff" element={<StaffManagement />} />
          <Route path="/admin/users" element={<UserManagement />} />
          <Route path="/admin/school-info" element={<SchoolInfo />} />
          <Route path="/admin/facilities" element={<FacilityList />} />
          <Route path="/admin/facility/:id" element={<FacilityDetails />} />
          <Route path="/admin/schedule" element={<RepairSchedule />} />
          <Route path="/admin/vendors" element={<VendorList />} />
          <Route path="/admin/budget" element={<BudgetManagement />} />
          <Route path="/admin/inventory" element={<Inventory />} />
          <Route path="/admin/safety" element={<SafetyInspection />} />
          <Route path="/admin/complaints" element={<ComplaintList />} />
          <Route path="/admin/analytics" element={<Analytics />} />

          {/* More pages will be added to reach 50+ */}
        </Routes>
      </main>
      <Footer />
    </div>
  );
}

export default App;
